Definition debruijn32 : list Z := debruijn32_tab.

Fixpoint Zseq (lo : Z) (n : nat) : list Z :=
  match n with O => [] | S n' => lo :: Zseq (lo + 1) n' end.

Lemma Zseq_In : forall n lo x, lo <= x < lo + Z.of_nat n -> In x (Zseq lo n).
