Lemma nth_flat_map2 : forall (l : list Z) k,
  (k < length l)%nat ->
  nth (2 * k) (flat_map (fun c => [c mod 256; c / 256]) l) 0 = nth k l 0 mod 256 /\
  nth (2 * k + 1) (flat_map (fun c => [c mod 256; c / 256]) l) 0 = nth k l 0 / 256.
