Lemma read_med_cnt : forall m j, rodata_clear m -> 0 <= j < 4 ->
  exists b, rdn ml_segs m (Z_to_bv 64 (T_MED_CNT + j)) 1 = Some [b] /\ bv_unsigned b = med_cnt j.
Proof.
