Lemma rodata_clear_wbytes : forall m a bs, rodata_clear m ->
  0 <= a < 2^64 -> a + Z.of_nat (length bs) <= 2^64 -> (a + Z.of_nat (length bs) <= IMG_LO \/ RW_LO <= a) ->
